122			}
123			if _, ok := s.users[m.UserID]; !ok {
124				return nil, fmt.Errorf("%w: member is unknown user %q", ErrInvalid, m.UserID)
125			}
126			s.members[memberKey{m.OrgID, m.UserID}] = m
127		}
128		for _, k := range st.APIKeys {
129			if err := dup("API key", k.ID, seen); err != nil {
130				return nil, err
131			}
132			if k.Token != "" { // a snapshot from before tokens were hashed: keep the key working, but store only its hash
133				k.Hash, k.Last4, k.Token = hashAPIKeyToken(k.Token), lastFour(k.Token), ""
134			}
135			s.apiKeys[k.ID] = k
136			if k.Hash != "" {
137				s.keysByHash[k.Hash] = k.ID
138			}
139		}
140		for _, i := range st.Invites {
141			if err := dup("invite", i.ID, seen); err != nil {
142				return nil, err
143			}
144			s.invites[i.ID] = i
145		}
146		for _, c := range st.Customers {
147			if err := dup("customer", c.ID, seen); err != nil {
148				return nil, err
149			}
150			s.customers[c.ID] = copyCustomer(c)
151			s.customersByEmail[normEmail(c.Email)] = c.ID
152		}
153		for _, p := range st.Plans {
154			if err := dup("plan", p.ID, seen); err != nil {
155				return nil, err
156			}
157			s.plans[p.ID] = p
158		}
159		for _, sub := range st.Subscriptions {
160			if err := dup("subscription", sub.ID, seen); err != nil {
161				return nil, err
162			}
163			s.subs[sub.ID] = copySub(sub)
164		}
165		s.usage = append(s.usage, st.Usage...)
166		for _, inv := range st.Invoices {
167			if err := dup("invoice", inv.ID, seen); err != nil {
168				return nil, err
169			}
170			s.invoices[inv.ID] = copyInvoice(inv)
171		}
172		for _, p := range st.Payments {
173			if err := dup("payment", p.ID, seen); err != nil {
174				return nil, err
175			}
176			s.payments[p.ID] = p
177		}
178		for _, ep := range st.WebhookEndpoints {
179			if err := dup("webhook endpoint", ep.ID, seen); err != nil {
180				return nil, err
181			}
182			s.endpoints[ep.ID] = copyEndpoint(ep)
183		}
184		for _, e := range st.Events {
185			if err := dup("event", e.ID, seen); err != nil {
